using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using HarmonyLib;
using UI.Builder;

namespace EnusDE.Signaltechnik {
    public sealed class HandbookChapter {
        public string Id,Title,Text;public bool EditorOnly;
    }
    public static class SignalHandbook {
        public static HandbookChapter[] Chapters(bool german,bool editor) {
            Func<string,string,string> text=(en,de)=>german?de:en;
            var chapters=new[]{
                new HandbookChapter{Id="signals",Title=text("Signals and diagram symbols","Signale und Gleisbildsymbole"),Text=text(
                    "<b>Hp 0 · Stop</b> — red. Do not pass without the required authority.\n<b>Hp 1 · Proceed</b> — green.\n<b>Hp 2 · Proceed at reduced speed</b> — green and yellow.\n<b>Sh 0 · Shunting stop</b> — two red lights.\n<b>Sh 1 · Shunting permitted</b> — two diagonal white lights.\n\nHigh and low main signals have the same functions. A main signal with shunting permission retains Hp 0 while displaying Sh 1.\n\nMain signal: one lamp symbol. Shunting signal: two lamps. Auxiliary destination: gold frame / Z; it has no physical signal. The arrow on the track shows diagram direction. Labels appear opposite the signal head.\n\nYellow track is unmonitored; red is occupied; green is a set route. Unknown detection never authorizes a movement. A repeated train-number display is read only and shows ? if its source is unavailable.",
                    "<b>Hp 0 · Halt</b> — rot. Nicht ohne erforderliche Zustimmung vorbeifahren.\n<b>Hp 1 · Fahrt</b> — grün.\n<b>Hp 2 · Langsamfahrt</b> — grün und gelb.\n<b>Sh 0 · Rangierhalt</b> — zwei rote Lichter.\n<b>Sh 1 · Rangieren erlaubt</b> — zwei schräg angeordnete weiße Lichter.\n\nHohe und niedrige Hauptsignale haben dieselben Funktionen. Bei einer Rangierfreigabe bleibt Hp 0 am Hauptsignal erhalten und Sh 1 leuchtet.\n\nHauptsignal: ein Lampensymbol. Rangiersignal: zwei Lampen. Hilfsziel: goldener Rahmen / Z; kein physisches Signal. Der Pfeil im Gleis zeigt die gezeichnete Richtung. Kennungen stehen gegenüber dem Signalkopf.\n\nGelbes Gleis ist nicht überwacht; Rot bedeutet besetzt, Grün eine festgelegte Fahrstraße. Unbekannte Freimeldung gibt keine Fahrt frei. Zugnummern-Anzeigekopien sind schreibgeschützt und zeigen bei fehlender Quelle ?." )},
                new HandbookChapter{Id="operations",Title=text("Driving and dispatching","Fahren und Fahrdienst"),Text=text(
                    "Route preparation is queued. You can select another start/destination while the first request is being prepared. In the dispatcher context, Pending requests and Progress show the work; Cancel pending preparations cancels only pending work, and STOP also cancels it. Duplicates are merged. Search uses an isolated snapshot; native protection is prepared over several frames. Every chain still needs current route, occupancy, point, flank, block and permission checks before admission. A queue entry is not a proceed authority. Existing active-route limits still apply.\n\n",
                    "Fahrstraßen werden in einer Warteschlange vorbereitet. Währenddessen kannst du das nächste Start-Ziel-Paar wählen. Im Bedienkontext zeigen Ausstehende Anforderungen und Fortschritt die Arbeit; Ausstehende Vorbereitungen abbrechen beendet nur wartende Arbeit, HALT bricht sie ebenfalls ab. Doppelte Anforderungen werden zusammengeführt. Die Suche nutzt eine getrennte Momentaufnahme; native Schutzbereiche werden über mehrere Frames vorbereitet. Vor dem Stellen gelten weiterhin aktuelle Fahrstraßen-, Belegungs-, Weichen-, Flanken-, Block- und Erlaubnisprüfungen. Ein Warteschlangeneintrag ist keine Fahrtzustimmung. Bestehende Grenzen aktiver Fahrstraßen gelten weiter.\n\n")+text("New in 0.7.23: routes are calculated when requested; no manual route definition is needed by default. An incomplete start selection expires after five seconds. Editor properties open in a separate window. Open a locomotive's Signalling tab, then Signalling information, for movement-role controls. Escape cancels construction placement; right mouse remains available for the camera.\n\n","Neu in 0.7.23: Fahrwege werden standardmäßig bei Anforderung berechnet, ohne manuelle Fahrwegdefinition. Eine unvollständige Startauswahl verfällt nach fünf Sekunden. Editor-Eigenschaften öffnen separat. Lokfenster → Signaltechnik → Signaltechnik-Fahrinformationen öffnet die Betriebsartwahl. Escape beendet die Bauplatzierung; rechts bleibt die Kamera bedienbar.\n\n")+text(
                    "Select a start signal, then a destination in the dispatcher diagram. Choose train, reduced-speed or shunting movement as appropriate. Auxiliary buttons can be route destinations or line-permission controls, as configured. A complete route chain reserves its path before giving a proceed aspect.\n\nA locomotive has three signal-system roles: Unassigned, Shunting, Train. Contact automation currently accepts explicitly assigned Train movements only. Assign the leading locomotive; other coupled locomotives remain unassigned. Reassign after changing the consist.\n\nAn occupied path, an opposing block direction or an unknown section prevents a new route. Use All routes and retained locks to identify the blocking route, including other interlockings. Stop does not immediately release a lock. A checked emergency release requires the configured time and a separate confirmation.\n\nThe current preview permits the host to configure and operate; clients receive the shared indication. It does not yet provide public player route requests or a dispatcher AI.",
                    "Im Fahrdienstleiter zuerst Startsignal, dann Ziel wählen. Zugfahrt, Langsamfahrt oder Rangierfahrt passend auswählen. Hilfstasten dienen je nach Einstellung als Fahrstraßenziel oder Erlaubnisbedienung. Eine vollständige Fahrstraßenfolge reserviert ihren Fahrweg vor der Fahrtstellung.\n\nFür Loks gibt es Keine Festlegung, Rangierfahrt und Zugfahrt. Die Kontakt-Automatik berücksichtigt derzeit nur ausdrücklich festgelegte Zugfahrten. Führende Lok festlegen; weitere gekuppelte Loks bleiben ohne Festlegung. Nach Änderung des Verbands neu festlegen.\n\nBelegter Fahrweg, Gegenrichtung im Block oder unbekannter Abschnitt verhindern eine neue Fahrstraße. Unter Alle Fahrstraßen und Restverschlüsse ist auch die blockierende Fahrt anderer Stellwerke sichtbar. Halt löst einen Verschluss nicht sofort. Geprüfte Hilfsauflösung benötigt Schutzzeit und gesonderte Bestätigung.\n\nIn dieser Testfassung konfiguriert und bedient der Host; Mitspieler erhalten die gemeinsame Anzeige. Öffentliche Spieleranträge und eine Fahrdienstleiter-KI sind noch nicht enthalten.")},
                new HandbookChapter{Id="construction",EditorOnly=true,Title=text("Construction and materials","Bauen und Material"),Text=text(
                    "Availability follows the map: when the native Whittier–Bryson signal milestone exists, its prerequisites also gate the independent Signal & Interlocking programme (base price $7,500); buying native CTC is not required. Without that milestone, signalling is immediately unlocked unless the map creator supplies a progression rule. Host overrides are under clock-toolbar launcher → Settings → Materials and construction costs. Existing unlocks and Sandbox remain available. The programme remains in progress permanently. It lists pending installations and their remaining materials. Existing installations are grandfathered when upgrading the mod.\n\nPlan signals in the construction menu. In a suitable supply wagon's Loads tab, order building supplies (FM flat car) or signal technology (XM boxcar) at an active interchange. Couple the wagons to a MOW car, activate its native equipment and stop within 250 track metres of the planned installation. Materials are consumed on completion. Depot unloading / manual completion remains available.\n\nSandbox builds immediately by default. Host options can require materials in Sandbox or allow free construction in economy mode.\n\nTo build a low main signal, place and click a shunting signal, then select Upgrade to low main signal. It keeps its ID, position, GFM box and route links. Full Hp 0 / Hp 1 / Hp 2 / Sh 1 is available. A locked signal cannot be rebuilt.",
                    "Die Freischaltung folgt der Karte: Ist der native Signal-Meilenstein Whittier–Bryson vorhanden, gelten dessen Voraussetzungen auch für den unabhängigen Signaltechnik-Ausbau (Grundpreis 7.500 $); der Kauf des nativen CTC ist nicht erforderlich. Ohne diesen Meilenstein ist die Signaltechnik sofort freigeschaltet, sofern der Kartenhersteller keine eigene Vorgabe mitliefert. Host-Vorgaben stehen unter Auswahlfenster an der Uhrleiste → Einstellungen → Material und Baukosten. Bestehende Freischaltungen und der Sandkasten bleiben verfügbar. Der Auftrag bleibt dauerhaft in Bearbeitung und zeigt offene Anlagen samt Restmaterial. Bestehende Anlagen bleiben bei einem Mod-Update freigeschaltet.\n\nSignale im Baumenü planen. Im Reiter Ladung eines passenden Materialwagens Baumaterial (FM-Flachwagen) oder Signaltechnik (XM-Güterwagen) am aktiven Übergabegleis bestellen. Wagen an einen MOW-Wagen kuppeln, dessen native Ausrüstung aktivieren und innerhalb von 250 Gleismetern bei der geplanten Anlage anhalten. Material wird beim Fertigstellen verbraucht. Materiallager und manuelles Fertigstellen bleiben verfügbar.\n\nDer Sandkasten baut standardmäßig sofort. Der Host kann Materialbedarf im Sandkasten einschalten oder im Wirtschaftsmodus kostenlos bauen.\n\nFür ein niedriges Hauptsignal ein Rangiersignal platzieren, anklicken und aufwerten. ID, Position, GFM-Kasten und Fahrstraßenverknüpfungen bleiben erhalten. Hp 0 / Hp 1 / Hp 2 / Sh 1 sind verfügbar. Ein verschlossenes Signal kann nicht umgebaut werden.")},
                new HandbookChapter{Id="automation",EditorOnly=true,Title=text("Automation, blocks and master interlocking","Automatik, Blöcke und ESTW"),Text=text(
                    "Open line / GWB: use Editor → Menu → Interlocking functions → Open line / GWB, or open it from the master interlocking. Create one entry per physical line track, choose neighbours and end signals, detect the route and apply after reviewing detection coverage. Single-track, directional and GWB modes are available. Place a Line permission module on a plain diagram rail; existing GFM bindings are retained. After initial whole-line clear proving, the configured normal end owns permission. The non-owning end requests permission; only its current owner can give it after complete clear proving and release of all route and residual locks. Automatic granting answers explicit requests only. Route requests never take permission from a neighbour. Permission never replaces a signal aspect.\n\nStart with two local interlockings, for example Whittier and Ela. Define their entry / exit signals and every required detection section. Point detection boxes are opt in: disabled points remain unmonitored. Confirm proposed detection sections before applying them.\n\nEnable AI signal integration, direction-block protection and contact automation. For each automatic signal, choose its primary target and optional alternate, allowed order types and retry interval. Place an approach contact on the track, set its direction and start signal, then enable it. Set a locomotive to Train and give it a valid road or waypoint order beyond the signal. An order ending before the signal does not request a route.\n\nDirection is coordinated from the real connected detection sections, including intervening block signals. An opposing request remains blocked while a related route or retained lock exists, or until the whole axis has cleared reliably. Contact axle counts are experimental and are not used to release occupancy.\n\nMaster modules reference local diagrams without creating additional signals or authorities. Place / move modules from the editor. Use the master diagram to operate shared routes. Central takeover pauses new automatic requests at selected stations; existing routes stay supervised. Resume explicitly afterwards. Hidden stations remain absent from the dispatcher diagram.\n\nTest in Sandbox with an approaching train, an opposing train and an occupied / unknown section. Confirm that no opposing permission occurs, alternate targets are tried, and train numbers advance through both stations.",
                    "Freie Strecke / GWB: Im Editor über Menü → Stellwerksfunktionen → Freie Strecke / GWB oder über das ESTW öffnen. Je physischem Streckengleis einen Eintrag anlegen, Nachbarn und Endsignale wählen, Verlauf erkennen und nach Prüfung der GFM-Abdeckung übernehmen. Eingleisige Strecke, Richtungsgleis und GWB sind möglich. Ein Streckenerlaubnismodul auf ein einfaches Gleisbildgleis setzen; vorhandene GFM-Zuordnungen bleiben erhalten. Nach vollständiger Start-Freiprüfung erhält die konfigurierte Regelseite die Erlaubnis. Die Gegenseite fragt an; nur der Inhaber darf nach vollständiger Freiprüfung und Auflösung aller Fahrstraßen/Restverschlüsse abgeben. Automatische Bestätigung beantwortet nur ausdrückliche Anfragen. Fahrstraßen nehmen dem Nachbarn keine Erlaubnis weg. Eine Erlaubnis ersetzt keinen Signalbegriff.\n\nMit zwei Ortsstellwerken beginnen, etwa Whittier und Ela. Ein-/Ausfahrsignale und alle nötigen Freimeldeabschnitte definieren. Weichenkästen sind optional: deaktivierte Weichen bleiben unüberwacht. Abschnittsvorschläge vor dem Übernehmen prüfen.\n\nAE-Signalanbindung, Blockrichtungsprüfung und Kontakt-Automatik aktivieren. Je Automatiksignal Erstziel, optionales Ausweichziel, zulässige Auftragsarten und Wiederholungsintervall wählen. Anforderungskontakt am Gleis platzieren, Richtung und Startsignal festlegen, dann aktivieren. Lok auf Zugfahrt setzen und einen gültigen Road-/Wegpunktauftrag über das Signal hinaus geben. Endet der Auftrag davor, wird keine Fahrstraße angefordert.\n\nDie Richtungsabstimmung entsteht aus den tatsächlich verbundenen Freimeldeabschnitten, auch über zwischenliegende Blocksignale. Gegenanforderungen bleiben gesperrt, solange zugehörige Fahrstraßen oder Restverschlüsse bestehen oder die gesamte Achse noch nicht verlässlich frei ist. Achszählungen am Kontakt sind experimentell und lösen keine Belegung auf.\n\nESTW-Module verweisen auf örtliche Tafeln, ohne Signale oder Zuständigkeiten zu verdoppeln. Module im Editor einfügen / verschieben. In der Gesamttafel dieselben Fahrstraßen bedienen. Die zentrale Übernahme pausiert neue automatische Anforderungen gewählter Betriebsstellen; bestehende Fahrstraßen bleiben überwacht. Anschließend ausdrücklich wieder einschalten. Verborgene Stellwerke erscheinen nicht im Fahrdienstleiter-Gleisbild.\n\nIm Sandkasten mit anfahrendem Zug, Gegenzug und besetztem / unbekanntem Abschnitt testen. Prüfen, dass keine Gegenfreigabe entsteht, Ausweichziele versucht werden und Zugnummern durch beide Bahnhöfe weiterwandern.")},
                new HandbookChapter{Id="hl",EditorOnly=true,Title=text("Hl signals · test package","Hl-Signale · Testpaket"),Text=text(
                    "Build → Hl main signal or Hl distant signal. Existing high H/V masts and distant signals can be converted in their properties without changing IDs or detection boundaries. Signal aspects follow Ril 301.0103. For a combined main, enable the distant function and assign its target; both functions share one screen. A standalone distant carries Ne2.\n\nThe live test maps existing clear and reduced permissions to unrestricted and 40 km/h displays. Hl1, Hl3a, Hl7, Hl9a, Hl10, Hl12a, Hp0 and Ra12 are supported. Only the upper announcing light flashes; the lower yellow remains steady. Full 60/100 km/h combinations are isolated in Guides/Hl-Signalbilder.html. Native AI speed handling is unchanged: exact 40/60/100 enforcement and braking need separate work and gameplay validation. Unbound and out-of-service states retain the existing cross and identification policy.",
                    "Bauen → Hl-Hauptsignal oder Hl-Vorsignal. Vorhandene hohe H/V-Masten und Vorsignale können in ihren Eigenschaften umgerüstet werden; IDs und GFM-Grenzen bleiben erhalten. Die Signalbilder folgen Ril 301.0103. Am Mehrabschnittssignal die Vorsignalfunktion aktivieren und das Ziel zuordnen; beide Funktionen nutzen denselben Schirm. Das einzelne Vorsignal trägt Ne2.\n\nDer Betriebstest bildet die vorhandenen Fahrt-/Langsamfahrtfreigaben ohne Signalbegrenzung beziehungsweise als 40-km/h-Anzeige ab. Hl1, Hl3a, Hl7, Hl9a, Hl10, Hl12a, Hp0 und Ra12 werden unterstützt. Nur das obere Ankündigungslicht blinkt; das untere gelbe Licht bleibt an. Die vollständigen 60/100-km/h-Kombinationen sind isoliert in Guides/Hl-Signalbilder.html dargestellt. Die native KI-Geschwindigkeitsbehandlung bleibt unverändert: exakte 40/60/100-Einhaltung und Bremsung benötigen getrennte Arbeit und Spieltests. Ungebunden/außer Betrieb verwenden weiterhin Kreuz und Kennlicht.")},
                new HandbookChapter{Id="backups",EditorOnly=true,Title=text("External backups and recovery","Externe Sicherungen und Wiederherstellung"),Text=text(
                    "Configuration is stored in the shared save for multiplayer and also backed up outside the mod folder, under EnusDE-Signaltechnik/Backups in the game's persistent user-data directory. Removing the mod folder does not remove these backups. Deleting the user-data directory does.\n\nUse Settings → Signal & Interlocking → Installation backup and recovery to create a manual copy, inspect a backup and restore it explicitly. Recovery requires a stopped world and no active routes or direction locks. Live signal permissions, occupancy and running train-number assignments are not restored. Automation stays disabled after recovery until checked.",
                    "Die Konfiguration liegt für Mehrspieler im gemeinsamen Spielstand und zusätzlich außerhalb des Modordners unter EnusDE-Signaltechnik/Backups im dauerhaften Benutzerdatenordner des Spiels. Das Entfernen des Modordners löscht diese Sicherungen nicht. Das Löschen des Benutzerdatenordners dagegen schon.\n\nUnter Einstellungen → Signaltechnik → Anlagensicherung und Wiederherstellung manuell sichern, Sicherungen prüfen und ausdrücklich wiederherstellen. Dafür müssen Züge stehen und Fahrstraßen sowie Richtungsbindungen vollständig aufgelöst sein. Laufende Fahrtfreigaben, Belegungen und aktuelle Zugnummernzuordnungen werden nicht wiederhergestellt. Die Automatik bleibt nach Wiederherstellung bis zur Prüfung deaktiviert.")}
            };
            return chapters.Where(c=>editor||!c.EditorOnly).ToArray();
        }
    }
    public sealed class HandbookIntegration:IDisposable {
        const string Owner="enusde.signaltechnik.guide",Prefix="enusde-signaltechnik-";
        readonly Harmony harmony;static Action<string> warning;
        public HandbookIntegration(Action<string> log){warning=log;harmony=new Harmony(Owner);harmony.Patch(AccessTools.Method(typeof(UI.Guide.GuideWindow),"Populate"),postfix:new HarmonyMethod(typeof(HandbookIntegration),nameof(Populated)));}
        static object Instance()=>AccessTools.PropertyGetter(typeof(UI.Guide.GuideWindow),"Instance")?.Invoke(null,null);
        public static void Open(){UI.Windows.WindowManager.Shared?.ShowWindow("Guide");var window=Instance();if(window!=null)AccessTools.Method(window.GetType(),"Show",new[]{typeof(string)}).Invoke(window,new object[]{Prefix+"signals"});}
        static void Populated(object __instance) {
            try {
                var type=__instance.GetType();var contents=AccessTools.Field(type,"_contents").GetValue(__instance) as IList;if(contents==null)return;
                Remove(contents);var document=type.GetNestedType("Document",BindingFlags.Public|BindingFlags.NonPublic);var ctor=document.GetConstructors(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance).Single(c=>c.GetParameters().Length==6);
                foreach(var chapter in SignalHandbook.Chapters(LocalText.German,Game.State.StateManager.IsHost)) {
                    var row=ctor.Invoke(new object[]{Prefix+chapter.Id,Prefix+chapter.Id,"EnusDE Signal & Interlocking",new Dictionary<string,string>(),chapter.Title,chapter.Text});
                    AccessTools.Field(document,"LinkAnchors").SetValue(row,new HashSet<string>());contents.Add(row);
                }
                (AccessTools.Field(type,"_panel").GetValue(__instance) as UIPanel)?.SetNeedsRebuild();
            }catch(Exception e){warning?.Invoke("Signal handbook: "+e.Message);}
        }
        static void Remove(IList contents){for(int i=contents.Count-1;i>=0;i--)if(((string)AccessTools.Property(contents[i].GetType(),"Identifier").GetValue(contents[i],null))?.StartsWith(Prefix,StringComparison.Ordinal)==true)contents.RemoveAt(i);}
        public void Dispose(){harmony.UnpatchAll(Owner);var window=AccessTools.Field(typeof(UI.Guide.GuideWindow),"_instance")?.GetValue(null);if(window!=null){var list=AccessTools.Field(window.GetType(),"_contents").GetValue(window) as IList;if(list!=null)Remove(list);(AccessTools.Field(window.GetType(),"_panel").GetValue(window) as UIPanel)?.SetNeedsRebuild();}warning=null;}
    }
}
